import 'dart:convert';
import 'dart:io';
import 'package:crypto/crypto.dart';
void main(){const p='/private/tmp/dart3d-u3-outline-first-target-control-20261028/r1/parent';final rows=<Map<String,Object>>[];for(final stage in ['baseline','control']){final path='$p/$stage/journey.mp4';final commands=<Map<String,Object>>[];ProcessResult run(String program,List<String>args,String suffix){final r=Process.runSync(program,args);File('$p/$stage/$suffix.log').writeAsStringSync(r.stderr.toString());commands.add({'program':program,'args':args,'exitCode':r.exitCode});if(r.exitCode!=0)throw StateError('$program failed $stage');return r;}final probe=run('ffprobe',['-v','error','-threads','2','-count_frames','-select_streams','v:0','-show_entries','stream=width,height,duration,nb_read_frames','-of','json',path],'probe');run('ffmpeg',['-v','warning','-threads','2','-i',path,'-map','0:v:0','-an','-fps_mode','passthrough','-f','null','-'],'decode');rows.add({'path':path,'sha256':sha256.convert(File(path).readAsBytesSync()).toString(),'probe':jsonDecode(probe.stdout.toString()),'commands':commands,'warningLines':File('$p/$stage/decode.log').readAsLinesSync().length});File('$p/video-receipts.json').writeAsStringSync(const JsonEncoder.withIndent('  ').convert(rows));print('$stage fully decoded ${(rows.last['probe'] as Map)['streams']}');}}
